// THE MAIN PAGE. form lives here. uses RatingStars + ChaiList.
import React, { useState, useEffect } from "react";
import RatingStars from "../components/RatingStars.jsx";
import ChaiList from "../components/ChaiList.jsx";

function Home({ entries = [], onAdd, onDelete }) {
  // TODO (later): make these controlled inputs
  const [style, setStyle] = useState("Masala");
  const [rating, setRating] = useState(3);
  const [notes, setNotes] = useState("");

  // TODO (optional later): fetch a quote/api on mount
  useEffect(() => {
    // example:
    // fetch("https://api.quotable.io/random")
    //   .then(r => r.json())
    //   .then(data => console.log("quote:", data));
  }, []);

  function handleSubmit(e) {
    e.preventDefault();
    if (!onAdd) return; // not wired yet—no stress

    // TODO (later): build a real entry object and call onAdd(entry)
    // const entry = {
    //   id: crypto.randomUUID?.() || String(Date.now()),
    //   dateISO: new Date().toISOString().slice(0,10),
    //   time: new Date().toTimeString().slice(0,5),
    //   style,
    //   rating,
    //   notes
    // };
    // onAdd(entry);
    // setNotes("");
  }

  return (
    <section className="page">
      <h1>ChaiLog (Home)</h1>

      {/* MINI FORM – placeholders only */}
      <form onSubmit={handleSubmit} className="card">
        <label>
          Style
          {/* TODO: controlled select later */}
          <select value={style} onChange={e => setStyle(e.target.value)}>
            <option>Masala</option>
            <option>Adrak</option>
            <option>Elaichi</option>
            <option>Kashmiri</option>
            <option>Cutting</option>
            <option>Other</option>
          </select>
        </label>

        <label>
          Notes
          {/* TODO: controlled textarea is already fine */}
          <textarea
            placeholder="what did it taste like?"
            value={notes}
            onChange={e => setNotes(e.target.value)}
          />
        </label>

        <RatingStars value={rating} onChange={setRating} />

        {/* submit does nothing yet; that’s okay */}
        <button type="submit">Save Cup (later)</button>
      </form>

      <ChaiList entries={entries} onDelete={onDelete} />
    </section>
  );
}

export default Home;
